                                                                   'users have '
                                                                   'reliable '
                                                                   'access). '
                                                                   'Defense-in-depth '
                                                                   'requires '
                                                                   'layered '
                                                                   'security '
                                                                   'controls '
                                                                   'rather '
                                                                   'than '
                                                                   'relying on '
                                                                   'a single '
                                                                   'perimeter '
                                                                   'firewall. '
                                                                   'STRIDE is '
                                                                   "Microsoft's "
                                                                   'threat '
                                                                   'modeling '
                                                                   'methodology '
                                                                   'categorizing '
                                                                   'threats '
                                                                   'into: '
                                                                   'Spoofing '
                                                                   'identity, '
                                                                   'Tampering '
                                                                   'with data, '
