                                                                   'and '
                                                                   'Elevation '
                                                                   'of '
                                                                   'privilege. '
                                                                   'Performing '
                                                                   'threat '
                                                                   'modeling '
                                                                   'during '
                                                                   'system '
                                                                   'design '
                                                                   'identifies '
                                                                   'vulnerabilities '
                                                                   'before '
