                                                                'distributed '
                                                                'master-worker '
                                                                'architecture. '
                                                                'The Control '
                                                                'Plane manages '
                                                                'cluster '
                                                                'state: the '
                                                                'API Server '
                                                                'serves as the '
                                                                'declarative '
                                                                'entry point '
                                                                'for all '
                                                                'commands, '
                                                                'etcd is a '
                                                                'distributed '
                                                                'key-value '
                                                                'store holding '
                                                                'the complete '
                                                                'cluster '
                                                                'state, the '
                                                                'Scheduler '
                                                                'assigns '
                                                                'unassigned '
                                                                'pods to '
                                                                'healthy '
                                                                'worker nodes '
                                                                'based on '
                                                                'resource '
                                                                'capacity, and '
                                                                'Controller '
                                                                'Managers '
                                                                'reconcile '
                                                                'actual state '
                                                                'against '
                                                                'desired '
                                                                'state. Worker '
                                                                'nodes run '
                                                                'application '
                                                                'workloads: '
                                                                'the Kubelet '
                                                                'communicates '
                                                                'with the API '
                                                                'server and '
                                                                'manages '
                                                                'container '
                                                                'lifecycles, '
