                                                            'web-api\n'
                                                            '  template:\n'
                                                            '    metadata:\n'
                                                            '      labels:\n'
                                                            '        app: '
                                                            'web-api\n'
                                                            '    spec:\n'
                                                            '      '
                                                            'containers:\n'
                                                            '      - name: '
                                                            'api\n'
                                                            '        image: '
                                                            'my-registry/web-api:1.0\n'
                                                            '        ports:\n'
                                                            '        - '
                                                            'containerPort: '
