                                                          'Revenue], '
                                                          'ALL(DimStore[Region]))\n'
                                                          'Percentage of Total '
                                                          '= DIVIDE([Total '
                                                          'Revenue], '
                                                          'CALCULATE([Total '
                                                          'Revenue], '
                                                          'ALL(FactSales)), '
                                                          '0)\n'
                                                          'High Value Sales = '
                                                          'CALCULATE([Total '
                                                          'Revenue], '
                                                          'FactSales[Revenue] '
                                                          '> 1000)',
