                                                         'BETWEEN, IN, LIKE), '
                                                         'allowing '
                                                         'applications to '
                                                         'retrieve only '
                                                         'records matching '
                                                         'specific criteria. '
                                                         'ORDER BY sorts '
                                                         'output rows '
                                                         'ascending (ASC) or '
                                                         'descending (DESC). '
                                                         'DISTINCT removes '
                                                         'duplicate rows from '
                                                         'the result set, and '
                                                         'LIMIT restricts the '
                                                         'number of returned '
