def normalize_skill_name(skill_name: str) -> str:
    """Normalize skill name for dictionary lookup."""
    clean = (skill_name or "").strip().lower()
    return SKILL_ALIASES.get(clean, clean)


def get_domain_for_skill(skill_name: str) -> Dict[str, Any]:
    """
    Resolve the domain roadmap family for any skill.
    Returns domain details and standard stages.
    """
    norm = normalize_skill_name(skill_name)
    
    # 1. Check if it's in our curated curricula
    if norm in SKILL_SPECIFIC_CURRICULA:
        dom_key = SKILL_SPECIFIC_CURRICULA[norm]["domain_key"]
        if dom_key in DOMAIN_ROADMAP_FAMILIES:
            return copy.deepcopy(DOMAIN_ROADMAP_FAMILIES[dom_key])

    # 2. Check keyword matching against domain categories
    for dom_key, kw_list in DOMAIN_KEYWORD_MAP.items():
        if any(kw in norm for kw in kw_list):
            return copy.deepcopy(DOMAIN_ROADMAP_FAMILIES[dom_key])
            
    # Default fallback domain
    return copy.deepcopy(DOMAIN_ROADMAP_FAMILIES["professional_methodologies"])


def get_curriculum_for_skill(skill_name: str) -> Dict[str, Any]:
    """
    Retrieve skill curriculum. If skill is specialized, returns rich curriculum with is_verified_specialized=True.
    If unsupported, returns an honest general engineering learning framework with is_verified_specialized=False.
    """
    norm = normalize_skill_name(skill_name)
    
    if norm in SKILL_SPECIFIC_CURRICULA:
        curr = copy.deepcopy(SKILL_SPECIFIC_CURRICULA[norm])
        curr["is_verified_specialized"] = True
        # Normalize resume_evidence to dict
        rev = curr.get("resume_evidence")
        if isinstance(rev, str):
            curr["resume_evidence"] = {
                "bullet_template": rev,
                "keywords": [curr.get("skill_name", norm)]
            }
        return curr
        
    # Honest fallback for unsupported skills
    domain_info = get_domain_for_skill(skill_name)
    display_title = skill_name.strip().title() if skill_name else "Target Skill"
    
    generic_stages = []
    base_stages = domain_info.get("stages", [])
    for idx, bs in enumerate(base_stages, 1):
        generic_stages.append({
            "stage_num": idx,
            "name": f"{display_title}: {bs.get('name', f'Stage {idx}')}",
            "task": f"Apply {display_title} principles to: {bs.get('task', '')}",
            "complete_explanation": (
                f"Developing competence in {display_title} requires structured progression through {bs.get('name', 'core concepts')}. "
                f"In this stage, focus on fundamental mechanisms, architectural role, and industry patterns. "
                f"Review standard documentation and build self-contained proofs of concept verifying behavior before production use."
            ),
            "concrete_example": f"Documented setup and functional proof-of-concept for {display_title} addressing {bs.get('name', 'stage objectives')}.",
            "exercise": f"Complete hands-on exercise exploring {bs.get('exercise', 'standard operations')} using {display_title}.",
            "deliverable": f"Verified working artifact and test notes for {display_title} {bs.get('name', '')}.",
            "verification_method": "Verify artifact against standard test cases and ensure code/documentation passes peer review."
        })
        
    return {
        "skill_name": display_title,
        "domain_key": "general_engineering",
        "domain_display": domain_info.get("domain_name", "General Technical Skill"),
        "why_it_matters": f"{display_title} is requested in the target job requirements. Mastery ensures production reliability and technical alignment.",
        "learning_objectives": [
            f"Understand core principles, architecture, and syntax of {display_title}",
            f"Build practical end-to-end components utilizing {display_title}",
            f"Verify behavior with automated tests and production error handling",
            f"Articulate engineering trade-offs in technical interviews"
        ],
        "prerequisites": domain_info.get("prerequisites", ["Foundational software engineering concepts"]),
        "fundamental_concepts": [f"{display_title} syntax & core concepts", f"{display_title} project setup", "Basic workflows"],
        "intermediate_concepts": ["Component integration", "Error handling & validation", "Testing & debugging"],
        "advanced_concepts": ["Performance optimization", "Production deployment", "Architectural trade-offs"],
        "stages": generic_stages,
        "practical_exercises": [
            f"Build a standalone prototype utilizing {display_title}",
            f"Implement comprehensive test suite for {display_title} component",
            f"Benchmark and document trade-offs for {display_title}"
        ],
        "mini_project": {
            "title": f"Production-Ready {display_title} Portfolio Prototype",
            "description": f"A complete end-to-end implementation demonstrating core capabilities of {display_title} integrated with existing portfolio projects.",
            "steps": [
                f"Set up local development and test environment for {display_title}",
                "Implement primary functional module and error handling",
                "Author unit and integration tests verifying happy and failure paths",
                "Document architecture, configuration, and API specifications"
            ],
            "verification": "All automated tests pass, zero unhandled errors, clean code style."
        },
        "testing_methods": ["Unit tests with standard assertions", "Integration tests verifying interface contracts"],
        "official_resources": [f"Official {display_title} Documentation", f"GitHub Open Source Reference Projects for {display_title}"],
        "interview_prep": [
            {
                "question": f"How do you evaluate and implement {display_title} in production systems?",
                "answer": (
                    f"When implementing {display_title}, I begin by assessing architectural fit, prerequisites, and integration boundaries. "
                    f"I establish clear automated test suites to verify behavior, manage configuration safely through environment variables, "
                    f"and measure latency and resource utilization to ensure scalability."
                ),
                "takeaway": f"Structure answers around architectural fit, testing, and production observability for {display_title}."
            }
        ],
        "resume_evidence": {
            "bullet_template": f"Implemented scalable {display_title} component, verifying functionality via automated test suites and reducing operational overhead.",
            "keywords": [display_title, "Engineering", "Testing", "Integration"]
        },
        "is_verified_specialized": False,
        "curriculum_notice": "General Engineering Learning Framework (Skill-Specific Curriculum Under Review)"
    }


def build_skill_action_plan(
    skill_name: str,
    priority_tier: str = "High",
    candidate_evidence: Optional[Dict[str, Any]] = None,
    daily_hours: float = 1.5,
    timeline_days: int = 14
) -> Dict[str, Any]:
    """
    Build a comprehensive 10-section action plan for a skill gap:
    1. Why this skill matters
    2. What the candidate currently knows (verified evidence or related foundations)
    3. What is not clearly demonstrated (specific missing depth from JD)
    4. What to learn next (ordered concept progression)
    5. Daily action plan (adapted to timeline: 3, 7, 14, or 30 days)
    6. Practical exercise (hands-on drill)
    7. Deliverable (tangible output)
    8. Verification method (objective criteria)
    9. Interview preparation (curated questions, answers, takeaways)
    10. Resume improvement (bullet point template and keywords)
    """
    curriculum = get_curriculum_for_skill(skill_name)
    candidate_evidence = candidate_evidence or {}
    
    # 1. Candidate foundation / current evidence analysis
    verified_skills = candidate_evidence.get("verified_skills", [])
    verified_skills_str = ", ".join(verified_skills[:4]) if verified_skills else "software engineering fundamentals"
    
    what_candidate_knows = (
        f"Your resume demonstrates verified experience in {verified_skills_str}. "
        f"You possess foundational engineering problem-solving and software development capabilities "
        f"that provide a solid foundation for acquiring {curriculum['skill_name']}."
    )
    
    # 2. What is not clearly demonstrated
    what_is_missing = (
        f"While your background demonstrates core technical competence, your resume does not yet clearly evidence "
        f"production-grade {curriculum['skill_name']} implementations, performance tuning, or architectural trade-off decisions. "
        f"Target roles require demonstrable hands-on experience delivering verified outcomes with this skill."
    )
    
    # 3. Daily action plan generation based on timeline
    daily_plan = []
    stages = curriculum.get("stages", [])
    
    if timeline_days <= 3:
        # Intensive 3-day sprint: Fundamentals, Core Hands-on, Verification
        daily_plan = [
            {
                "period": "Day 1 (Core Foundations)",
                "hours": round(daily_hours, 1),
                "focus": stages[0]["name"] if len(stages) > 0 else "Fundamentals",
                "task": stages[0]["task"] if len(stages) > 0 else "Review core syntax and architectural concepts.",
                "deliverable": stages[0].get("deliverable", "Basic proof-of-concept.")
            },
            {
                "period": "Day 2 (Applied Implementation)",
                "hours": round(daily_hours, 1),
                "focus": stages[2]["name"] if len(stages) > 2 else (stages[1]["name"] if len(stages) > 1 else "Hands-on Development"),
                "task": stages[2]["task"] if len(stages) > 2 else "Build functional component handling core operational scenarios.",
                "deliverable": stages[2].get("deliverable", "Functional module with error handling.")
            },
            {
                "period": "Day 3 (Verification & Interview Prep)",
                "hours": round(daily_hours, 1),
                "focus": "Testing & Interview Readiness",
                "task": "Author automated tests, document code, and practice answering technical interview questions.",
                "deliverable": "Completed project repository, test pass report, and interview talking points."
            }
        ]
    elif timeline_days <= 7:
        # 7-day pacing: 1 stage per day
        for i in range(min(7, len(stages))):
            st = stages[i]
            daily_plan.append({
                "period": f"Day {i+1}",
                "hours": round(daily_hours, 1),
                "focus": st["name"],
                "task": st["task"],
                "deliverable": st.get("deliverable", "Stage deliverable.")
            })
    elif timeline_days <= 14:
        # 14-day pacing: 2 days per stage
        for i in range(min(7, len(stages))):
            st = stages[i]
            start_day = (i * 2) + 1
            end_day = (i * 2) + 2
            daily_plan.append({
                "period": f"Days {start_day}-{end_day}",
                "hours": round(daily_hours * 2, 1),
                "focus": st["name"],
                "task": f"Day {start_day}: Deep dive into concepts and guided examples. Day {end_day}: {st['exercise']}",
                "deliverable": st.get("deliverable", "Stage deliverable.")
            })
    else:
        # 30-day comprehensive mastery: ~4 days per stage
        for i in range(min(7, len(stages))):
            st = stages[i]
            start_day = (i * 4) + 1
            end_day = min(30, (i + 1) * 4)
            daily_plan.append({
                "period": f"Days {start_day}-{end_day}",
                "hours": round(daily_hours * 4, 1),
                "focus": st["name"],
                "task": f"In-depth mastery: {st['task']}. Complete practical lab: {st['exercise']}. Document architectural decisions.",
                "deliverable": st.get("deliverable", "Comprehensive deliverable.")
            })

    # Pick practical exercise and deliverable
    sample_stage = stages[min(3, len(stages)-1)] if stages else {}
    practical_exercise = sample_stage.get("exercise", f"Build a practical {curriculum['skill_name']} module.")
    deliverable = sample_stage.get("deliverable", f"Documented {curriculum['skill_name']} implementation with tests.")
    verification_method = sample_stage.get("verification_method", "Pass automated test suite with zero errors.")
    
    # Total estimated study hours
    total_hours = round(daily_hours * timeline_days, 1)

    return {
        "skill_name": curriculum["skill_name"],
        "priority_tier": priority_tier,
        "is_verified_specialized": curriculum.get("is_verified_specialized", False),
        "curriculum_notice": curriculum.get("curriculum_notice"),
        "domain_display": curriculum.get("domain_display", "Engineering"),
        "total_estimated_hours": total_hours,
        "timeline_days": timeline_days,
        "daily_hours": daily_hours,
        # Section 1: Why it matters
        "why_it_matters": curriculum["why_it_matters"],
        # Section 2: What candidate knows
        "what_candidate_knows": what_candidate_knows,
        # Section 3: What is missing
        "what_is_missing": what_is_missing,
        # Section 4: What to learn next
        "what_to_learn_next": {
            "fundamentals": curriculum.get("fundamental_concepts", []),
            "intermediate": curriculum.get("intermediate_concepts", []),
            "advanced": curriculum.get("advanced_concepts", [])
        },
        # Section 5: Daily action plan
        "daily_action_plan": daily_plan,
        # Section 6: Practical exercise
        "practical_exercise": practical_exercise,
        # Section 7: Deliverable
        "deliverable": deliverable,
        # Section 8: Verification method
        "verification_method": verification_method,
        # Section 9: Interview preparation
        "interview_prep": curriculum.get("interview_prep", []),
        # Section 10: Resume improvement
        "resume_improvement": curriculum.get("resume_evidence", {
            "bullet_template": f"Built production-ready {curriculum['skill_name']} component, improving system reliability and passing rigorous automated validation.",
            "keywords": [curriculum["skill_name"]]
        }),
        # Full curriculum access for expandable stages
        "stages": stages,
        "mini_project": curriculum.get("mini_project"),
        "official_resources": curriculum.get("official_resources", [])
    }
